gadq(){return"\u0645\u0633\u062d \u0628\u0627\u0631\u0643\u0648\u062f \u0639\u0644\u0628\u0629 \u0645\u0627\u062f\u0629 \u064a\u0633\u062d\u0628 \u0639\u0644\u0628\u0629 \u0648\u0627\u062d\u062f\u0629 \u0645\u0646 \u0627\u0644\u0645\u062e\u0632\u0646 \u0628\u0627\u0633\u0645\u0643."},
gadr(){return"\u0647\u0630\u0627 \u0627\u0644\u0628\u0627\u0631\u0643\u0648\u062f \u063a\u064a\u0631 \u0645\u0631\u062a\u0628\u0637 \u0628\u0623\u064a \u0645\u0627\u062f\u0629 \u0641\u064a \u0627\u0644\u0645\u062e\u0632\u0646 \u0628\u0639\u062f \u2014 \u0627\u0637\u0644\u0628 \u0645\u0646 \u0627\u0644\u0645\u0633\u0624\u0648\u0644 \u0631\u0628\u0637\u0647."},
