gaaR(){return"\u0646\u06cc\u0633\u0628\u06d5 \u0644\u06d5\u0633\u06d5\u0631 \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627\u0646\u06cc \u0626\u06d5\u0645 \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u06d5 \u0644\u06d5 \u0695\u06c6\u0698\u06cc \u062f\u0648\u0627\u06cc \u0626\u06d5\u0645 \u0695\u06c6\u0698\u06d5\u0648\u06d5 \u062a\u0627 \u0647\u06d5\u0645\u0627\u0646 \u0695\u06c6\u0698\u06cc \u0645\u0627\u0646\u06af\u06cc \u062f\u0627\u0647\u0627\u062a\u0648\u0648 \u062f\u06d5\u0698\u0645\u06ce\u0631\u062f\u0631\u06ce\u062a (\u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5 4 = \u0644\u06d5 5\u0640\u06d5\u0648\u06d5 \u062a\u0627 4). \u0628\u06d5\u062a\u0627\u06b5\u06cc \u0628\u0647\u06ce\u06b5\u06d5 \u0628\u06c6 \u0645\u0627\u0646\u06af\u06cc \u0632\u0627\u06cc\u06cc\u0646\u06cc."},
gPD(){return"\u0646\u06cc\u0633\u0628\u06d5"},
gPC(){return"\u0647\u06cc\u0686 \u0646\u06cc\u0633\u0628\u06d5\u06cc\u06d5\u06a9 \u0628\u06c6 \u06a9\u06d5\u06cc\u0633\u06d5 \u062f\u0648\u0648\u0628\u0627\u0631\u06d5\u06a9\u0631\u0627\u0648\u06d5\u06a9\u0627\u0646 \u0646\u06cc\u06cc\u06d5"},
gPB(){return"\u06a9\u06d5\u06cc\u0633\u06d5 \u062f\u0648\u0648\u0628\u0627\u0631\u06d5\u06a9\u0631\u0627\u0648\u06d5\u06a9\u0627\u0646 \u0644\u06d5 \u0646\u06cc\u0633\u0628\u06d5\u06cc \u0647\u06cc\u0686 \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u06ce\u06a9 \u0646\u0627\u0698\u0645\u06ce\u0631\u062f\u0631\u06ce\u0646. \u0644\u06d5\u0633\u06d5\u0631 \u0626\u06d5\u0648 \u0645\u0627\u0646\u06af\u0627\u0646\u06d5\u06cc \u0645\u0648\u0648\u0686\u06d5 \u062c\u06ce\u0628\u06d5\u062c\u06ce \u062f\u06d5\u0628\u06ce\u062a \u06a9\u06d5 \u0644\u06d5 \u0626\u06ce\u0633\u062a\u0627\u0648\u06d5 \u062f\u0631\u0648\u0633\u062a \u062f\u06d5\u06a9\u0631\u06ce\u0646."},
