gaim(){return"\u0628\u06c6 \u062f\u06d5\u0633\u062a\u06af\u06d5\u06cc\u0634\u062a\u0646\u06cc \u062a\u06d5\u0648\u0627\u0648 \u0628\u06d5\u062a\u0627\u06b5\u06cc \u0628\u0647\u06ce\u06b5\u06d5\u0631\u06d5\u0648\u06d5. \u06cc\u06d5\u06a9 \u06cc\u0627\u0646 \u0686\u06d5\u0646\u062f \u067e\u06c6\u0644\u06ce\u06a9 \u0647\u06d5\u06b5\u0628\u0698\u06ce\u0631\u06d5 \u0648 \u0626\u06d5\u0645 \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u06d5 \u062a\u06d5\u0646\u0647\u0627 \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627\u0646\u06cc \u0626\u06d5\u0648 \u067e\u06c6\u0644\u0627\u0646\u06d5 \u062f\u06d5\u0628\u06cc\u0646\u06ce\u062a \u0648 \u06a9\u0627\u0631\u06cc\u0627\u0646 \u0644\u06d5\u0633\u06d5\u0631 \u062f\u06d5\u06a9\u0627\u062a\u060c \u0644\u06d5 \u0647\u06d5\u0645\u0648\u0648 \u0628\u06d5\u0634\u06d5\u06a9\u0627\u0646\u06cc \u0626\u06d5\u067e\u06d5\u06a9\u06d5\u062f\u0627. \u0628\u06d5\u0695\u06ce\u0648\u06d5\u0628\u06d5\u0631 \u0647\u06d5\u0631\u06af\u06cc\u0632 \u0633\u0646\u0648\u0648\u0631\u062f\u0627\u0631 \u0646\u0627\u06a9\u0631\u06ce\u062a. \u062f\u06d5\u0633\u062a\u06af\u06d5\u06cc\u0634\u062a\u0646 \u0628\u06d5 \u067e\u0627\u0631\u06d5\u062f\u0627\u0646\u06d5\u06a9\u0627\u0646 \u06cc\u0627\u0646 \u0695\u0627\u067e\u06c6\u0631\u062a\u06d5\u06a9\u0627\u0646 \u0645\u06d5\u062f\u06d5 \u0628\u06d5 \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u06cc \u0633\u0646\u0648\u0648\u0631\u062f\u0627\u0631: \u06a9\u06c6\u06a9\u0631\u0627\u0648\u06d5\u06a9\u0627\u0646\u06cc \u062a\u06d5\u0646\u0647\u0627 \u0626\u06d5\u0648 \u067e\u06c6\u0644\u0627\u0646\u06d5 \u062f\u06d5\u06af\u0631\u0646\u06d5\u0648\u06d5."},
RL(a,b){return"\u0634\u0648\u06ce\u0646\u06cc \u0628\u06d5\u06a9\u0627\u0631\u0647\u0627\u062a\u0648\u0648: "+a+" \u0644\u06d5 "+b+" GB \u06cc \u0628\u06ce \u0628\u06d5\u0631\u0627\u0645\u0628\u06d5\u0631"},
RK(a,b,c){return""+a+" GB \u0644\u06d5\u06af\u06d5\u06b5 \u0628\u06d5\u0634\u062f\u0627\u0631\u06cc\u06d5\u06a9\u06d5\u062f\u0627\u06cc\u06d5. \u0644\u06d5\u0648\u06d5 \u0632\u06cc\u0627\u062a\u0631\u060c "+b+" \u0628\u06c6 \u0647\u06d5\u0631 100 GB \u0644\u06d5 \u0633\u0627\u06b5\u06ce\u06a9\u062f\u0627\u060c \u0628\u06d5\u067e\u06ce\u06cc \u062a\u06ce\u06a9\u0695\u0627\u06cc \u0628\u06d5\u06a9\u0627\u0631\u0647\u06ce\u0646\u0627\u0646\u062a \u0644\u06d5 \u0661\u0662 \u0645\u0627\u0646\u06af\u06cc \u0695\u0627\u0628\u0631\u062f\u0648\u0648\u062f\u0627 (\u0626\u06ce\u0633\u062a\u0627 "+c+")."},
RJ(a){return"\u062a\u06ce\u0686\u0648\u0648\u06cc \u0686\u0627\u0648\u06d5\u0695\u0648\u0627\u0646\u06a9\u0631\u0627\u0648\u06cc \u0634\u0648\u06ce\u0646\u06cc \u0647\u06d5\u06b5\u06af\u0631\u062a\u0646 \u0628\u06c6 \u0626\u06d5\u0645 \u0633\u0627\u06b5: "+a},
ga0T(){return"\u0646\u0627\u0631\u062f\u0646"},
