gamm(){return"\u0646\u0627\u0648 (\u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5: \u0686\u0627\u067e\u062e\u0627\u0646\u06d5)"},
gamj(){return"\u062f\u0631\u0648\u0633\u062a\u06a9\u0631\u062f\u0646\u06cc \u0628\u06d5\u0633\u062a\u06d5\u0631"},
gaml(){return"\u0626\u06d5\u0645 \u0628\u06d5\u0633\u062a\u06d5\u0631\u06d5 \u0628\u06c6 \u067e\u06d5\u06cc\u0648\u06d5\u0646\u062f\u06cc\u06cc\u06d5\u06a9\u06d5 \u0628\u0646\u06ce\u0631\u06d5. \u0644\u06d5 \u062a\u06d5\u0644\u06d5\u06af\u0631\u0627\u0645\u062f\u0627 \u062f\u06d5\u06cc\u06a9\u0627\u062a\u06d5\u0648\u06d5 \u0648 \u06cc\u06d5\u06a9 \u062c\u0627\u0631 Start \u062f\u0627\u062f\u06d5\u06af\u0631\u06ce\u062a. \u062a\u06d5\u0646\u0647\u0627 \u06cc\u06d5\u06a9 \u062c\u0627\u0631 \u0648 \u0644\u06d5 \u0645\u0627\u0648\u06d5\u06cc \u0662\u0664 \u06a9\u0627\u062a\u0698\u0645\u06ce\u0631\u062f\u0627 \u06a9\u0627\u0631 \u062f\u06d5\u06a9\u0627\u062a."},
gamk(){return"\u06cc\u0627\u0646\u060c \u0628\u06c6 \u0626\u06d5\u0648\u06d5\u06cc \u0647\u06d5\u0645\u0648\u0648 \u0626\u06d5\u0648 \u06a9\u0627\u063a\u06d5\u0632\u0627\u0646\u06d5 \u0628\u0628\u06cc\u0646\u06cc\u062a \u06a9\u06d5 \u062f\u06d5\u06cc\u0646\u06ce\u0631\u06cc\u062a: \u06af\u0631\u0648\u0648\u067e\u06ce\u06a9\u06cc \u062a\u06d5\u0644\u06d5\u06af\u0631\u0627\u0645 \u0644\u06d5\u06af\u06d5\u06b5 \u067e\u06d5\u06cc\u0648\u06d5\u0646\u062f\u06cc\u06cc\u06d5\u06a9\u06d5 \u062f\u0631\u0648\u0633\u062a \u0628\u06a9\u06d5\u060c \u067e\u0627\u0634\u0627\u0646 \u0626\u06d5\u0645 \u0628\u06d5\u0633\u062a\u06d5\u0631\u06d5 \u0628\u06a9\u06d5\u0631\u06d5\u0648\u06d5 \u0648 \u0626\u06d5\u0648 \u06af\u0631\u0648\u0648\u067e\u06d5 \u0647\u06d5\u06b5\u0628\u0698\u06ce\u0631\u06d5. \u06a9\u0627\u063a\u06d5\u0632\u06d5\u06a9\u0627\u0646 \u0628\u06c6 \u0647\u06d5\u0631\u062f\u0648\u0648\u06a9\u062a\u0627\u0646 \u0644\u06d5 \u06af\u0631\u0648\u0648\u067e\u06d5\u06a9\u06d5\u062f\u0627 \u062f\u06ce\u0646. \u062a\u06d5\u0646\u0647\u0627 \u06cc\u06d5\u06a9\u06ce\u06a9 \u0644\u06d5\u0645 \u062f\u0648\u0648 \u0628\u06d5\u0633\u062a\u06d5\u0631\u06d5 \u0628\u06d5\u06a9\u0627\u0631\u0628\u0647\u06ce\u0646\u06d5."},
amn(a,b){return a+" \xb7 \u0686\u0627\u0648\u06d5\u0695\u06ce\u06cc Start (\u0628\u06d5\u0633\u062a\u06d5\u0631\u06d5\u06a9\u06d5 \u062a\u0627 "+b+" \u06a9\u0627\u0631 \u062f\u06d5\u06a9\u0627\u062a)"},
gamo(){return"\u0644\u0627\u0628\u0631\u062f\u0646"},
gamq(){return"\u0626\u06d5\u0645 \u067e\u06d5\u06cc\u0648\u06d5\u0646\u062f\u06cc\u06cc\u06d5 \u0644\u0627\u0628\u0628\u0631\u06ce\u062a\u061f"},
amp(a){return"\xab"+a+"\xbb \u0686\u06cc\u062a\u0631 \u06a9\u0627\u063a\u06d5\u0632\u06cc \u06a9\u06d5\u06cc\u0633 \u0648\u06d5\u0631\u0646\u0627\u06af\u0631\u06ce\u062a. \u062f\u06d5\u062a\u0648\u0627\u0646\u06cc\u062a \u0628\u06d5 \u0628\u06d5\u0633\u062a\u06d5\u0631\u06ce\u06a9\u06cc \u0646\u0648\u06ce \u062f\u0648\u0648\u0628\u0627\u0631\u06d5 \u0632\u06cc\u0627\u062f\u06cc \u0628\u06a9\u06d5\u06cc\u062a\u06d5\u0648\u06d5."},
gPH(){return"\u0647\u06d5\u0646\u0627\u0631\u062f\u06d5\u06a9\u0631\u062f\u0646\u06cc \u062f\u0627\u062a\u0627\u06a9\u0627\u0646\u0645"},
gPI(){return"\u06a9\u06c6\u067e\u06cc\u06cc\u06d5\u06a9\u06cc \u062a\u06d5\u0648\u0627\u0648\u06cc \u062f\u0627\u062a\u0627\u06cc \u062a\u0627\u0642\u06cc\u06af\u06d5\u06a9\u06d5\u062a \u0644\u06d5\u0633\u06d5\u0631 \u0626\u0627\u0645\u06ce\u0631\u06cc \u062e\u06c6\u062a \u2014 \u0628\u06c6 \u0647\u06d5\u06b5\u06af\u0631\u062a\u0646\u060c \u0648 \u0628\u06c6 \u062e\u0648\u06ce\u0646\u062f\u0646\u06d5\u0648\u06d5 \u0628\u06d5\u0628\u06ce \u0626\u06d5\u067e \u0648 \u0628\u06d5\u0628\u06ce \u0626\u06cc\u0646\u062a\u06d5\u0631\u0646\u06ce\u062a."},
ga77(){return"\u0641\u0627\u06cc\u0644\u06ce\u06a9\u06cc zip \u0648\u06d5\u0631\u062f\u06d5\u06af\u0631\u06cc\u062a \u06a9\u06d5 \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627\u0646\u060c \u067e\u0627\u0631\u06d5\u062f\u0627\u0646\u06d5\u06a9\u0627\u0646\u060c \u0642\u06d5\u0631\u0632\u06d5\u06a9\u0627\u0646\u060c \u062a\u06ce\u0686\u0648\u0648\u06d5\u06a9\u0627\u0646\u060c \u0645\u0648\u0648\u0686\u06d5\u06a9\u0627\u0646\u060c \u062f\u0627\u0628\u06cc\u0646\u06a9\u06d5\u0631\u0627\u0646 \u0648 \u0632\u06cc\u0627\u062a\u0631\u06cc \u0648\u06d5\u06a9 \u062e\u0634\u062a\u06d5 (\u0641\u0627\u06cc\u0644\u06cc CSV \u06a9\u06d5 \u0644\u06d5 Excel \u062f\u06d5\u06a9\u0631\u06ce\u0646\u06d5\u0648\u06d5) \u062a\u06ce\u062f\u0627\u06cc\u06d5\u060c \u0644\u06d5\u06af\u06d5\u06b5 \u067e\u06d5\u0695\u06d5\u06cc\u06d5\u06a9 \u0628\u06d5 \u0646\u0627\u0648\u06cc index.html \u06a9\u06d5 \u0644\u06d5 \u0647\u06d5\u0631 \u0648\u06ce\u0628\u06af\u06d5\u0695\u06ce\u06a9 \u062f\u06d5\u06a9\u0631\u06ce\u062a\u06d5\u0648\u06d5 \u2014 \u0628\u06d5 \u06af\u06d5\u0695\u0627\u0646\u060c \u0628\u06d5\u0628\u06ce \u0626\u06cc\u0646\u062a\u06d5\u0631\u0646\u06ce\u062a \u0648 \u0628\u06d5\u0628\u06ce \u0626\u06d5\u067e. zip \u0628\u06a9\u06d5\u0631\u06d5\u0648\u06d5 \u0648 \u062f\u0648\u0648 \u062c\u0627\u0631 \u06a9\u0644\u06cc\u06a9 \u0644\u06d5 index.html \u0628\u06a9\u06d5."},
