gMb(){return"\u0632\u06ce\u062f\u06d5\u06a9\u0631\u0646\u0627 \u067e\u06d5\u06cc\u0648\u06d5\u0646\u062f\u06cc\u06ce"},
gamm(){return"\u0646\u0627\u06a4 (\u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5: \u0686\u0627\u067e\u062e\u0627\u0646\u06d5)"},
gamj(){return"\u062f\u0631\u0648\u0633\u062a\u06a9\u0631\u0646\u0627 \u0644\u06cc\u0646\u06a9\u06cc"},
