amn(a,b){return a+" \xb7 \u0686\u0627\u06a4\u06d5\u0695\u06ce\u06cc Start (\u0644\u06cc\u0646\u06a9 \u0647\u06d5\u062a\u0627 "+b+" \u06a9\u0627\u0631 \u062f\u06a9\u06d5\u062a)"},
gamo(){return"\u0644\u0627\u0628\u0631\u0646"},
gamq(){return"\u0626\u06d5\u06a4 \u067e\u06d5\u06cc\u0648\u06d5\u0646\u062f\u06cc\u06d5 \u0628\u0647\u06ce\u062a\u06d5 \u0644\u0627\u0628\u0631\u0646\u061f"},
amp(a){return"\xab"+a+"\xbb \u0686\u06cc\u062f\u06cc \u06a9\u0627\u063a\u06d5\u0632\u06ce\u0646 \u06a9\u06d5\u06cc\u0633\u0627\u0646 \u0648\u06d5\u0631\u0646\u0627\u06af\u0631\u06cc\u062a. \u062a\u0648 \u062f\u0634\u06ce\u06cc \u0628 \u0644\u06cc\u0646\u06a9\u06d5\u06a9\u06ce \u0646\u0648\u0648 \u062f\u0648\u0648\u0628\u0627\u0631\u06d5 \u0632\u06ce\u062f\u06d5 \u0628\u06a9\u06d5\u06cc."},
gPH(){return"\u0647\u06d5\u0646\u0627\u0631\u062f\u06d5\u06a9\u0631\u0646\u0627 \u062f\u0627\u062a\u0627\u06cc\u06ce\u0646 \u0645\u0646"},
gPI(){return"\u06a9\u06c6\u067e\u06cc\u06cc\u06d5\u06a9\u0627 \u062a\u06d5\u0645\u0627\u0645 \u06cc\u0627 \u062f\u0627\u062a\u0627\u06cc\u06ce\u0646 \u062a\u0627\u0642\u06cc\u06af\u06d5\u0647\u0627 \u062a\u06d5 \u0644 \u0633\u06d5\u0631 \u0626\u0627\u0645\u06ce\u0631\u06ce \u062e\u06c6 \u2014 \u0628\u06c6 \u067e\u0627\u0631\u0627\u0633\u062a\u0646\u06ce \u0648 \u0628\u06c6 \u062e\u0648\u0627\u0646\u062f\u0646\u06ce \u0628\u06ce\u06cc \u0626\u06d5\u067e \u0648 \u0628\u06ce\u06cc \u0626\u06cc\u0646\u062a\u06d5\u0631\u0646\u06ce\u062a."},
ga77(){return"\u062a\u0648 \u0641\u0627\u06cc\u0644\u06d5\u06a9\u06ce zip \u0648\u06d5\u0631\u062f\u06af\u0631\u06cc \u06a9\u0648 \u06a9\u06d5\u06cc\u0633\u060c \u067e\u0627\u0631\u06d5\u062f\u0627\u0646\u060c \u0642\u06d5\u0631\u0632\u060c \u062e\u06d5\u0631\u062c\u06cc\u060c \u0645\u0648\u0648\u0686\u06d5\u060c \u062f\u0627\u0628\u06cc\u0646\u06a9\u06d5\u0631 \u0648 \u067e\u062a\u0631 \u0648\u06d5\u06a9 \u062e\u0634\u062a\u06d5 \u062a\u06ce\u062f\u0627 \u0647\u06d5\u0646\u06d5 (\u0641\u0627\u06cc\u0644\u06ce\u0646 CSV \u06cc\u06ce\u0646 \u062f Excel \u062f\u0627 \u062f\u0647\u06ce\u0646\u06d5 \u06a4\u06d5\u06a9\u0631\u0646)\u060c \u0628 \u067e\u06d5\u0695\u06d5\u06a9\u06ce \u0628 \u0646\u0627\u06a4\u06ce index.html \u06a4\u06d5 \u06a9\u0648 \u062f \u0647\u06d5\u0631 \u0648\u06ce\u0628\u06af\u06d5\u0695\u06d5\u06a9\u06ce \u062f\u0627 \u062f\u0647\u06ce\u062a\u06d5 \u06a4\u06d5\u06a9\u0631\u0646 \u2014 \u0628 \u06af\u06d5\u0695\u0627\u0646\u060c \u0628\u06ce\u06cc \u0626\u06cc\u0646\u062a\u06d5\u0631\u0646\u06ce\u062a \u0648 \u0628\u06ce\u06cc \u0626\u06d5\u067e. zip \u06a4\u06d5\u06a9\u06d5 \u0648 \u062f\u0648\u0648 \u062c\u0627\u0631\u0627\u0646 \u06a9\u0644\u06cc\u06a9 \u0644 index.html \u0628\u06a9\u06d5."},
