ga6A(){return"\u062f\u0627\u062a\u0627\u06cc\u06ce\u0646 \u0645\u0646 \u062f\u0627\u0628\u06d5\u0632\u06cc\u0646\u06d5"},
a70(a){return"\u062e\u0648\u0627\u0646\u062f\u0646\u0627 "+a+"\u2026"},
gIT(){return"\u0686\u06ce\u06a9\u0631\u0646\u0627 zip\u2026"},
